import{_ as e,o,c as d,a2 as a}from"./chunks/framework.BGlkWkwp.js";const m=JSON.parse('{"title":"Modal","description":"","frontmatter":{},"headers":[],"relativePath":"components/modal.md","filePath":"components/modal.md"}'),r={name:"components/modal.md"};function n(s,t,c,i,h,l){return o(),d("div",null,[...t[0]||(t[0]=[a('<h1 id="modal" tabindex="-1">Modal <a class="header-anchor" href="#modal" aria-label="Permalink to &quot;Modal&quot;">​</a></h1><p>Modal is a container laid over the screen for one task.</p><h2 id="when-to-use" tabindex="-1">When to use <a class="header-anchor" href="#when-to-use" aria-label="Permalink to &quot;When to use&quot;">​</a></h2><p>Use it when a task stops the work: a form to fill in, a choice to make. A question before an action is a <a href="./confirm">Confirm</a>; a few settings next to their trigger are a <a href="./popover">Popover</a>; something to look at while working is a panel or a <a href="./drawer">Drawer</a>. A modal has one primary action, a title that says what it does, and two ways to close: Escape and the close button. A modal does not open another modal.</p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Prop</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>open</code></td><td><code>false</code></td><td>Whether it is open (bindable)</td></tr><tr><td><code>title</code></td><td>required</td><td>The title in the head</td></tr><tr><td><code>size</code></td><td><code>md</code></td><td>The width: <code>sm</code>, <code>md</code>, <code>lg</code> or <code>xl</code></td></tr><tr><td><code>confirm</code></td><td><code>false</code></td><td>A confirmation: small, centred, the scrim ignored</td></tr><tr><td><code>persistent</code></td><td><code>false</code></td><td>No close button; Escape and the scrim do nothing</td></tr><tr><td><code>flush</code></td><td><code>false</code></td><td>The body has no padding; the content holds its own</td></tr><tr><td><code>status</code></td><td></td><td>A status at the left end of the Footer</td></tr><tr><td><code>onclose</code></td><td></td><td>Called once when it closes, however it closes</td></tr><tr><td><code>onback</code></td><td></td><td>On a full screen, the head starts with back instead</td></tr><tr><td><code>children</code></td><td>required</td><td>The body</td></tr><tr><td><code>sub</code></td><td></td><td>A band under the head, for steps (a snippet)</td></tr><tr><td><code>lead</code></td><td></td><td>The left end of the Footer (a snippet)</td></tr><tr><td><code>secondary</code></td><td></td><td>A secondary action (a snippet)</td></tr><tr><td><code>cancel</code></td><td></td><td>The cancel button (a snippet)</td></tr><tr><td><code>primary</code></td><td></td><td>The primary button (a snippet)</td></tr><tr><td><code>inline</code></td><td><code>false</code></td><td>The same surface in the flow, for documentation</td></tr></tbody></table><h2 id="contract" tabindex="-1">Contract <a class="header-anchor" href="#contract" aria-label="Permalink to &quot;Contract&quot;">​</a></h2><p>A modal is a <code>&lt;dialog&gt;</code> opened with <code>showModal()</code>: the page behind is inert, the focus stays inside and a scrim covers the rest. From top to bottom it holds the head (a <a href="./toolbar">Toolbar</a> with an h2 title on one line and a close button, a line below), the band for steps, the body and the <a href="./footer">Footer</a>, which orders the actions. Only the body shrinks and scrolls. The body has pad-md inside and its children are gap-md apart. The width is 25, 35, 45 or 60rem and the modal is at least gap-lg from the edges of the screen. It opens with the focus on the first input of the body, else on the primary action (a confirmation, on its first action). Escape, the close button and a press on the scrim close it (a confirmation ignores the scrim, a persistent modal ignores all three). Below 48rem it fills the screen: the close button (or back) starts the head, the primary action ends it, and the other actions move to the end of the body. Its messages are <code>close</code> and <code>back</code>.</p><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><figure class="kata-example"><iframe src="/kata/examples/modal/" title="Modal" loading="lazy" style="width:100%;height:32rem;border:1px solid var(--vp-c-divider);border-radius:8px;"></iframe><figcaption><a href="/kata/examples/modal/" target="_blank" rel="noopener">Modal</a></figcaption></figure>',10)])])}const f=e(r,[["render",n]]);export{m as __pageData,f as default};
